class BankAccount:
    def __init__(self, initial_balance=0):
        self.balance = initial_balance

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            print(f"Deposit Successful. Balance: {self.balance}")
        else:
            print("Deposit amount must be positive.")

    def withdraw(self, amount):
        if amount > 0 and self.balance >= amount:
            self.balance -= amount
            print(f"Withdraw Successful. Balance: {self.balance}")
        else:
            print("Insufficient funds or withdrawal amount is zero.")

    def check_balance(self):
        print(f"Balance: {self.balance}")


# Create a bank account
account = BankAccount()

# Perform operations
operation = input("Enter 'd' for deposit, 'w' for withdraw, or 'c' for check balance: ").lower()

if operation == 'd':
    deposit_amount = float(input("Enter deposit amount: "))
    account.deposit(deposit_amount)
elif operation == 'w':
    withdraw_amount = float(input("Enter withdraw amount: "))
    account.withdraw(withdraw_amount)
elif operation == 'c':
    account.check_balance()
else:
    print("Invalid operation. Please try again.")
```

This program defines a `BankAccount` class with methods for depositing, withdrawing, and checking the balance. The main part of the program prompts the user to enter an operation and then calls the appropriate method based on the user's input.
